    // ---- Mini-batch Xor ----

    #[tokio::test(flavor = "current_thread")]
    async fn xor_complete_truth_table() {
        // T xor T → F, T xor F → T, F xor T → T, F xor F → F.
        for (l, r, expected) in [
            (true, true, false),
            (true, false, true),
            (false, true, true),
            (false, false, false),
        ] {
            let e = binop(
                BinOpKind::Xor,
                Expr::Bool(l, Span::ZERO),
                Expr::Bool(r, Span::ZERO),
            );
            assert_eq!(
                eval_expr_test(e).await.unwrap(),
                Value::Bool(expected),
                "xor({}, {}) expected {}",
                l,
                r,
                expected
            );
        }
    }

