    #[tokio::test(flavor = "current_thread")]
    async fn assign_defines_new_variable_in_local_scope() {
        let env = Environment::new();
        let stmt = Stmt::Assign {
            target: AssignTarget::Ident("x".into(), Span::default()),
            type_: None,
            value: Expr::Int(42, Span::ZERO),
            span: Span::ZERO,
        };
        eval_stmt(&stmt, env.clone()).await.unwrap();

        assert_eq!(env.lock().get("x"), Some(Value::Int(42)));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn assign_reassigns_existing_variable_in_same_scope() {
        let env = Environment::new();
        env.lock().define("x", Value::Int(1));

        let stmt = Stmt::Assign {
            target: AssignTarget::Ident("x".into(), Span::default()),
            type_: None,
            value: Expr::Int(99, Span::ZERO),
            span: Span::ZERO,
        };
        eval_stmt(&stmt, env.clone()).await.unwrap();

        assert_eq!(env.lock().get("x"), Some(Value::Int(99)));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn assign_from_child_reassigns_in_parent_if_exists() {
        let global = Environment::new();
        global.lock().define("x", Value::Int(1));

        let child = Environment::new_child(global.clone());
        let stmt = Stmt::Assign {
            target: AssignTarget::Ident("x".into(), Span::default()),
            type_: None,
            value: Expr::Int(42, Span::ZERO),
            span: Span::ZERO,
        };
        eval_stmt(&stmt, child).await.unwrap();

        // The change is visible in the global.
        assert_eq!(global.lock().get("x"), Some(Value::Int(42)));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn assign_creates_local_if_variable_does_not_exist_in_chain() {
        let global = Environment::new();
        let child = Environment::new_child(global.clone());

        let stmt = Stmt::Assign {
            target: AssignTarget::Ident("nueva".into(), Span::default()),
            type_: None,
            value: Expr::Int(7, Span::ZERO),
            span: Span::ZERO,
        };
        eval_stmt(&stmt, child.clone()).await.unwrap();

        // Only exists in child, didn't propagate to the parent.
        assert_eq!(child.lock().get("nueva"), Some(Value::Int(7)));
        assert_eq!(global.lock().get("nueva"), None);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn assign_ignores_type_annotation() {
        // type_: Some("Int") with String value — doesn't fail
        // (gradual typing, no runtime checks yet).
        let env = Environment::new();
        let stmt = Stmt::Assign {
            target: AssignTarget::Ident("x".into(), Span::default()),
            type_: Some(TypeExpr::named("Int")),
            value: Expr::Str("soy un string".into(), Span::ZERO),
            span: Span::ZERO,
        };
        assert!(eval_stmt(&stmt, env.clone()).await.is_ok());
        assert_eq!(
            env.lock().get("x"),
            Some(Value::Str("soy un string".into()))
        );
    }

    // ---- Expr::Call (builtins) ----

    #[tokio::test(flavor = "current_thread")]
    async fn call_to_print_returns_null() {
        // print(...) writes to stdout and returns Null. We verify the
        // return Value; the actual output is checked manually with hello.fitz.
        let env = Environment::new();
        register_builtins(&env);

        let call = Expr::Call {
            callee: Box::new(Expr::Ident("print".into(), Span::ZERO)),
            args: vec![Expr::Str("test".into(), Span::ZERO)],
            span: Span::ZERO,
        };
        assert_eq!(eval_expr(&call, env).await.unwrap(), Value::Null);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn call_to_undefined_function_is_error() {
        // Since `Expr::Call` now evaluates the callee as an
        // expression, an undefined ident fails with
        // `UndefinedVariable` (not `UndefinedFunction` as before).
        // It's consistent: the parser doesn't syntactically
        // distinguish "this is a function name".
        let env = Environment::new();
        let call = Expr::Call {
            callee: Box::new(Expr::Ident("noexiste".into(), Span::ZERO)),
            args: vec![],
            span: Span::ZERO,
        };
        assert!(matches!(
            eval_expr(&call, env).await.unwrap_err(),
            EvalSignal::Error(FitzError {
                kind: ErrorKind::UndefinedVariable(_),
                ..
            })
        ));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn call_to_non_function_is_type_error() {
        let env = Environment::new();
        env.lock().define("x", Value::Int(5));

        let call = Expr::Call {
            callee: Box::new(Expr::Ident("x".into(), Span::ZERO)),
            args: vec![],
            span: Span::ZERO,
        };
        assert!(matches!(
            eval_expr(&call, env).await.unwrap_err(),
            EvalSignal::Error(FitzError {
                kind: ErrorKind::TypeMismatch { .. },
                ..
            })
        ));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn call_evaluates_args_before_invoking() {
        // The `1 + 2` arg must reach the builtin as Int(3), not as
        // a BinOp. Since print doesn't let us inspect, we use an
        // indirect assert: if arg eval failed, it would error. If it
        // arrives fine, Null.
        let env = Environment::new();
        register_builtins(&env);

        let call = Expr::Call {
            callee: Box::new(Expr::Ident("print".into(), Span::ZERO)),
            args: vec![Expr::BinOp {
                op: BinOpKind::Add,
                left: Box::new(Expr::Int(1, Span::ZERO)),
                right: Box::new(Expr::Int(2, Span::ZERO)),
                span: Span::ZERO,
            }],
            span: Span::ZERO,
        };
        assert_eq!(eval_expr(&call, env).await.unwrap(), Value::Null);
    }

