    // ---- Mini integration: hello.fitz by hand ----

    // ---- FnDef + Return + Call (user-defined) ----

    /// Helper: builds `fn name(params) { body }` as a Stmt.
    fn fn_def(name: &str, params: Vec<&str>, body: Vec<Stmt>) -> Stmt {
        Stmt::FnDef {
            name: name.into(),
            params: params
                .into_iter()
                .map(|p| crate::ast::Param {
                    name: p.into(),
                    type_: None,
                    default: None,
                    varargs: false,
                    name_span: Span::default(),
                })
                .collect(),
            return_type: None,
            body,
            is_async: false,
            decorators: vec![],
            span: Span::ZERO,
        }
    }

    #[tokio::test(flavor = "current_thread")]
    async fn fn_without_return_returns_null() {
        // fn f() { } ; f()
        let env = Environment::new();
        eval_stmt(&fn_def("f", vec![], vec![]), env.clone())
            .await
            .unwrap();

        let call = Expr::Call {
            callee: Box::new(Expr::Ident("f".into(), Span::ZERO)),
            args: vec![],
            span: Span::ZERO,
        };
        assert_eq!(eval_expr(&call, env).await.unwrap(), Value::Null);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn fn_returns_constant() {
        // fn f() { return 42 } ; f()
        let env = Environment::new();
        eval_stmt(
            &fn_def(
                "f",
                vec![],
                vec![Stmt::Return(Expr::Int(42, Span::ZERO), Span::ZERO)],
            ),
            env.clone(),
        )
        .await
        .unwrap();

        let call = Expr::Call {
            callee: Box::new(Expr::Ident("f".into(), Span::ZERO)),
            args: vec![],
            span: Span::ZERO,
        };
        assert_eq!(eval_expr(&call, env).await.unwrap(), Value::Int(42));
    }

