    // ---- Expr::If ----

    /// Helper: builds `if cond { then } else? { else_ }`.
    fn if_expr(cond: Expr, then: Vec<Stmt>, else_: Option<Vec<Stmt>>) -> Expr {
        Expr::If {
            condition: Box::new(cond),
            then,
            else_,
            span: Span::ZERO,
        }
    }

    #[tokio::test(flavor = "current_thread")]
    async fn if_true_without_else_returns_then_value() {
        // if true { 7 } → 7 (no else needed when cond is true)
        let e = if_expr(
            Expr::Bool(true, Span::ZERO),
            vec![Stmt::Expr(Expr::Int(7, Span::ZERO), Span::ZERO)],
            None,
        );
        assert_eq!(eval_expr_test(e).await.unwrap(), Value::Int(7));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn if_false_without_else_returns_null() {
        let e = if_expr(
            Expr::Bool(false, Span::ZERO),
            vec![Stmt::Expr(Expr::Int(7, Span::ZERO), Span::ZERO)],
            None,
        );
        assert_eq!(eval_expr_test(e).await.unwrap(), Value::Null);
    }

    #[tokio::test(flavor = "current_thread")]
    async fn if_else_takes_correct_branch() {
        // if true { 1 } else { 2 } → 1 (then branch when cond true)
        let then = vec![Stmt::Expr(Expr::Int(1, Span::ZERO), Span::ZERO)];
        let else_ = vec![Stmt::Expr(Expr::Int(2, Span::ZERO), Span::ZERO)];
        let e = if_expr(
            Expr::Bool(true, Span::ZERO),
            then.clone(),
            Some(else_.clone()),
        );
        assert_eq!(eval_expr_test(e).await.unwrap(), Value::Int(1));

        let e = if_expr(Expr::Bool(false, Span::ZERO), then, Some(else_));
        assert_eq!(eval_expr_test(e).await.unwrap(), Value::Int(2));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn if_condition_non_bool_is_type_error() {
        // if 1 { ... } → error (no truthy coercion in Fitz).
        let e = if_expr(Expr::Int(1, Span::ZERO), vec![], None);
        assert!(matches!(
            eval_expr_test(e).await.unwrap_err(),
            EvalSignal::Error(FitzError {
                kind: ErrorKind::TypeMismatch { .. },
                ..
            })
        ));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn if_evaluates_only_matching_branch() {
        // The then is an undefined Ident. If evaluated, it would
        // error. Since cond is false, it's not touched → result of else.
        let then = vec![Stmt::Expr(
            Expr::Ident("no_existe".into(), Span::ZERO),
            Span::ZERO,
        )];
        let else_ = vec![Stmt::Expr(Expr::Int(99, Span::ZERO), Span::ZERO)];
        let e = if_expr(Expr::Bool(false, Span::ZERO), then, Some(else_));
        assert_eq!(eval_expr_test(e).await.unwrap(), Value::Int(99));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn variables_defined_inside_if_persist_outside() {
        // x = 1
        // if x == 1 { y = 99 }
        // print(y)  → "99" (vars assigned in if persist outside)
        let env = Environment::new();
        env.lock().define("x", Value::Int(1));

        let if_stmt = Stmt::Expr(
            if_expr(
                Expr::BinOp {
                    op: BinOpKind::Eq,
                    left: Box::new(Expr::Ident("x".into(), Span::ZERO)),
                    right: Box::new(Expr::Int(1, Span::ZERO)),
                    span: Span::ZERO,
                },
                vec![Stmt::Assign {
                    target: AssignTarget::Ident("y".into(), Span::default()),
                    type_: None,
                    value: Expr::Int(99, Span::ZERO),
                    span: Span::ZERO,
                }],
                None,
            ),
            Span::ZERO,
        );
        eval_stmt(&if_stmt, env.clone()).await.unwrap();

        assert_eq!(env.lock().get("y"), Some(Value::Int(99)));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn nested_else_if_works() {
        // if false { 1 } else if true { 2 } else { 3 } → 2
        //
        // The parser models `else if` as `else_: vec![Stmt::Expr(Expr::If, Span::ZERO)]`.
        let inner = if_expr(
            Expr::Bool(true, Span::ZERO),
            vec![Stmt::Expr(Expr::Int(2, Span::ZERO), Span::ZERO)],
            Some(vec![Stmt::Expr(Expr::Int(3, Span::ZERO), Span::ZERO)]),
        );
        let outer = if_expr(
            Expr::Bool(false, Span::ZERO),
            vec![Stmt::Expr(Expr::Int(1, Span::ZERO), Span::ZERO)],
            Some(vec![Stmt::Expr(inner, Span::ZERO)]),
        );
        assert_eq!(eval_expr_test(outer).await.unwrap(), Value::Int(2));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn if_as_expression_in_assign() {
        // let r = if true { 42 } else { 0 } (if as expression in assign)
        let env = Environment::new();
        let stmt = Stmt::Assign {
            target: AssignTarget::Ident("r".into(), Span::default()),
            type_: None,
            value: if_expr(
                Expr::Bool(true, Span::ZERO),
                vec![Stmt::Expr(Expr::Int(42, Span::ZERO), Span::ZERO)],
                Some(vec![Stmt::Expr(Expr::Int(0, Span::ZERO), Span::ZERO)]),
            ),
            span: Span::ZERO,
        };
        eval_stmt(&stmt, env.clone()).await.unwrap();
        assert_eq!(env.lock().get("r"), Some(Value::Int(42)));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn recursive_factorial_works() {
        // The test that ties everything: closures + recursion + if +
        // comparison + BinOp + Return.
        //
        //   fn factorial(n) {
        //       if n == 0 { return 1 }
        //       return n * factorial(n - 1)
        //   }
        //   factorial(5) → 120
        let env = Environment::new();

        let body = vec![
            Stmt::Expr(
                if_expr(
                    Expr::BinOp {
                        op: BinOpKind::Eq,
                        left: Box::new(Expr::Ident("n".into(), Span::ZERO)),
                        right: Box::new(Expr::Int(0, Span::ZERO)),
                        span: Span::ZERO,
                    },
                    vec![Stmt::Return(Expr::Int(1, Span::ZERO), Span::ZERO)],
                    None,
                ),
                Span::ZERO,
            ),
            Stmt::Return(
                Expr::BinOp {
                    op: BinOpKind::Mul,
                    left: Box::new(Expr::Ident("n".into(), Span::ZERO)),
                    right: Box::new(Expr::Call {
                        callee: Box::new(Expr::Ident("factorial".into(), Span::ZERO)),
                        args: vec![Expr::BinOp {
                            op: BinOpKind::Sub,
                            left: Box::new(Expr::Ident("n".into(), Span::ZERO)),
                            right: Box::new(Expr::Int(1, Span::ZERO)),
                            span: Span::ZERO,
                        }],
                        span: Span::ZERO,
                    }),
                    span: Span::ZERO,
                },
                Span::ZERO,
            ),
        ];

        eval_stmt(&fn_def("factorial", vec!["n"], body), env.clone())
            .await
            .unwrap();

        let call = Expr::Call {
            callee: Box::new(Expr::Ident("factorial".into(), Span::ZERO)),
            args: vec![Expr::Int(5, Span::ZERO)],
            span: Span::ZERO,
        };
        assert_eq!(eval_expr(&call, env).await.unwrap(), Value::Int(120));
    }

    // ---- Expr::Match ----

    use crate::ast::MatchArm;

    fn match_arm(pattern: Pattern, body: Expr) -> MatchArm {
        MatchArm {
            pattern,
            guard: None,
            body: vec![Stmt::Expr(body, Span::ZERO)],
        }
    }

