    #[tokio::test(flavor = "current_thread")]
    async fn match_ok_wildcard_does_not_pollute_scope() {
        // After a match with Ok(_), there should be no var named
        // `_` in the env. This was the bug that 3.3 closed.
        let src = "\
let x = match Ok(5) {\n\
    Ok(_) => 1\n\
    _ => 0\n\
}\n\
print(_)\n";
        let result = parse_and_eval(src).await;
        assert!(
            result.is_err(),
            "expected error of unknown `_` variable, was: {:?}",
            result
        );
    }

