    // ---- while / loop ----

    #[tokio::test(flavor = "current_thread")]
    async fn while_iterates_until_cond_is_false() {
        // i = 0
        // total = 0
        // while i < 5 { total = total + i; i = i + 1 }
        // total → 0+1+2+3+4 = 10
        let env = Environment::new();
        env.lock().define("i", Value::Int(0));
        env.lock().define("total", Value::Int(0));

        let stmt = Stmt::While {
            condition: Expr::BinOp {
                op: BinOpKind::Lt,
                left: Box::new(Expr::Ident("i".into(), Span::ZERO)),
                right: Box::new(Expr::Int(5, Span::ZERO)),
                span: Span::ZERO,
            },
            body: vec![
                Stmt::Assign {
                    target: AssignTarget::Ident("total".into(), Span::default()),
                    type_: None,
                    value: Expr::BinOp {
                        op: BinOpKind::Add,
                        left: Box::new(Expr::Ident("total".into(), Span::ZERO)),
                        right: Box::new(Expr::Ident("i".into(), Span::ZERO)),
                        span: Span::ZERO,
                    },
                    span: Span::ZERO,
                },
                Stmt::Assign {
                    target: AssignTarget::Ident("i".into(), Span::default()),
                    type_: None,
                    value: Expr::BinOp {
                        op: BinOpKind::Add,
                        left: Box::new(Expr::Ident("i".into(), Span::ZERO)),
                        right: Box::new(Expr::Int(1, Span::ZERO)),
                        span: Span::ZERO,
                    },
                    span: Span::ZERO,
                },
            ],
            label: None,
            span: Span::ZERO,
        };
        eval_stmt(&stmt, env.clone()).await.unwrap();
        assert_eq!(env.lock().get("total"), Some(Value::Int(10)));
    }

