    // ---- Stmt::TypeDef ----

    use crate::ast::Field;

    fn make_field(name: &str, type_: &str, nullable: bool) -> Field {
        let base = TypeExpr::named(type_);
        let t = if nullable {
            TypeExpr::Nullable(Box::new(base))
        } else {
            base
        };
        Field {
            name: name.into(),
            type_: t,
            default: None,
            decorators: vec![],
        }
    }

    #[tokio::test(flavor = "current_thread")]
    async fn type_def_registers_type_in_env() {
        // type User { id: Int, name: Str }
        let env = Environment::new();
        let stmt = Stmt::TypeDef {
            name: "User".into(),
            fields: vec![
                make_field("id", "Int", false),
                make_field("name", "Str", false),
            ],
            methods: vec![],
            decorators: vec![],
            span: Span::ZERO,
        };
        eval_stmt(&stmt, env.clone()).await.unwrap();

        let v = env
            .lock()
            .get("User")
            .expect("User did not stay in the env");
        match v {
            Value::Type { name, fields, .. } => {
                assert_eq!(name, "User");
                assert_eq!(fields.len(), 2);
                assert_eq!(fields[0].name, "id");
                assert_eq!(fields[1].name, "name");
            }
            other => panic!("expected Value::Type, got {:?}", other),
        }
    }

