    // ---- Mini-batch Ir — iteradores sobre Range ----

    #[tokio::test(flavor = "current_thread")]
    async fn ir_range_enumerate_returns_index_value_pairs() {
        let (env, res) = parse_eval_into_env("let r = (0..3).enumerate()").await;
        res.unwrap();
        let v = env.lock().get("r").unwrap();
        if let Value::List(items) = v {
            let g = items.lock();
            assert_eq!(g.len(), 3);
            // Each element is Tuple([Int, Int]) with (i, n).
            for (idx, item) in g.iter().enumerate() {
                if let Value::Tuple(t) = item {
                    assert_eq!(t.len(), 2);
                    assert_eq!(t[0], Value::Int(idx as i64));
                    assert_eq!(t[1], Value::Int(idx as i64));
                } else {
                    panic!("expected Tuple, saw {:?}", item);
                }
            }
        } else {
            panic!("expected List");
        }
    }

