        // is released before `env` is dropped at end of scope.
        let p = env.lock().get("p").unwrap();
        match p {
            Value::Float(f) => {
                assert!((f - std::f64::consts::PI).abs() < 1e-15, "got {}", f);
            }
            other => panic!("expected Float, was {:?}", other),
        }
