        let src = "\
            @post(\"/users\")\nfn create(name) => name\n\
            @put(\"/users/{id}\")\nfn update(id: Int, name) => name\n\
            @delete(\"/users/{id}\")\nfn del(id: Int) => 0\n\
        ";
        let (res, reg) =
            crate::http::with_active_registry_async(|| async { parse_and_eval(src).await }).await;
        res.unwrap();
