    // ---- Mini-batch Async-cl: async fn as inline closure ----

    #[tokio::test(flavor = "current_thread")]
    async fn async_cl_inline_returns_future() {
        // `async fn(...) => ...` produces a Value::Function with
        // is_async = true. On invocation, returns a lazy Value::Future
        // the caller must `.await`.
        let (env, res) = parse_eval_into_env(
            "async fn run() -> Int {\n\
                 let f = async fn(n: Int) -> Int { return n * 2 }\n\
                 let r = f(21).await\n\
                 return r\n\
             }\n\
             let r: Int = run().await",
        )
        .await;
        res.unwrap();
        assert_eq!(env.lock().get("r"), Some(Value::Int(42)));
    }

    #[tokio::test(flavor = "current_thread")]
    async fn async_cl_inline_with_sleep_inside() {
        let (env, res) = parse_eval_into_env(
            "async fn run() -> Int {\n\
                 let delayed = async fn(n: Int) -> Int {\n\
                     sleep(1).await\n\
                     return n + 100\n\
                 }\n\
                 let r = delayed(5).await\n\
                 return r\n\
             }\n\
             let r: Int = run().await",
        )
        .await;
        res.unwrap();
        assert_eq!(env.lock().get("r"), Some(Value::Int(105)));
    }

