    #[test]
    fn auth_module_pre_registered_and_accepts_field_access() {
        // Verifies that `auth` is registered as Value::Module and that
        // `auth.blacklist`/`auth.is_blacklisted`/`auth.cleanup_expired`
        // are accessible as builtins.
        let env = Environment::new();
        register_builtins(&env);
        let auth = env.lock().get("auth").expect("auth should be bound");
        match auth {
            Value::Module { name, env } => {
                assert_eq!(name, "auth");
                let g = env.lock();
                assert!(matches!(g.get("blacklist"), Some(Value::Builtin { .. })));
                assert!(matches!(
                    g.get("is_blacklisted"),
                    Some(Value::Builtin { .. })
                ));
                assert!(matches!(
                    g.get("cleanup_expired"),
                    Some(Value::Builtin { .. })
                ));
            }
            other => panic!("expected Value::Module, received {:?}", other),
        }
    }

    /// End-to-end test using the real evaluator (not a direct call
    /// to the builtin fn). Verifies that `jwt.encode(...)` parsed as
    /// a Fitz expression runs correctly via normal
    /// field-access dispatch on Value::Module.
    #[tokio::test(flavor = "current_thread")]
    async fn jwt_and_hash_via_field_access_in_fitz_program() {
        let (env, res) = parse_eval_into_env(
            "let token = jwt.encode({\"sub\": \"x\"}, \"secret-32-bytes-aaaaaaaaaaaaaaaaa\")\n\
             let pw = hash.password(\"pass\")\n\
             let ok = hash.verify(\"pass\", pw)\n\
             let bad = hash.verify(\"otra\", pw)",
        )
        .await;
        res.unwrap();
        let env = env.lock();
        // token is Str with 3 JWT parts.
        match env.get("token").expect("token bindeado") {
            Value::Str(s) => assert_eq!(s.split('.').count(), 3),
            other => panic!("token should be Str, was {:?}", other),
        }
        // pw is PHC Argon2id string.
        match env.get("pw").expect("pw bindeado") {
            Value::Str(s) => assert!(s.starts_with("$argon2id$")),
            other => panic!("pw should be Str, was {:?}", other),
        }
        assert_eq!(env.get("ok"), Some(Value::Bool(true)));
        assert_eq!(env.get("bad"), Some(Value::Bool(false)));
    }

