    // ---- Phase 10.3.b3 — order_by/limit/offset/first/count ----

    /// Local helper: builds an empty QueryBuilder for tests
    /// of build_select_sql directly, without depending on the full
    /// evaluator.
    fn empty_state() -> QueryBuilderState {
        QueryBuilderState {
            type_name: "User".into(),
            fields: vec![
                crate::ast::Field {
                    name: "id".into(),
                    type_: crate::ast::TypeExpr::named("Int"),
                    default: None,
                    decorators: vec![],
                },
                crate::ast::Field {
                    name: "name".into(),
                    type_: crate::ast::TypeExpr::named("Str"),
                    default: None,
                    decorators: vec![],
                },
                crate::ast::Field {
                    name: "age".into(),
                    type_: crate::ast::TypeExpr::named("Int"),
                    default: None,
                    decorators: vec![],
                },
            ],
            meta: crate::types::TableMetadata {
                sql_name: "users".into(),
                primary_fields: vec!["id".into()],
                columns: std::collections::HashMap::new(),
                relations: std::collections::HashMap::new(),
                renamed_from: None,
                schema: None,
                indexes: vec![],
                check_constraints: vec![],
            },
            where_sql: None,
            where_args: Vec::new(),
            order_by_clauses: Vec::new(),
            limit: None,
            offset: None,
            group_by_clauses: Vec::new(),
        }
    }

    #[test]
    fn build_sql_without_where_or_clauses() {
        let s = empty_state();
        let sql = build_select_sql(&s, None);
        assert_eq!(sql, "SELECT \"id\", \"name\", \"age\" FROM \"users\"");
    }

    #[test]
    fn build_sql_with_where_and_order_by() {
        let mut s = empty_state();
        s.where_sql = Some("(\"age\" > $1)".into());
        s.where_args = vec![crate::db::PgValue::Int(18)];
        s.order_by_clauses.push("\"age\" DESC".into());
        s.order_by_clauses.push("\"name\" ASC".into());
        let sql = build_select_sql(&s, None);
        assert_eq!(
            sql,
            "SELECT \"id\", \"name\", \"age\" FROM \"users\" WHERE (\"age\" > $1) ORDER BY \"age\" DESC, \"name\" ASC"
        );
    }

    // Extracts the single order-by clause from the QueryBuilder returned by
    // `orm_qb_order_by`.
    fn one_order_clause(v: Value) -> String {
        let arc = match v {
            Value::QueryBuilder(a) => a,
            _ => panic!("expected QueryBuilder"),
        };
        let st = arc.downcast::<QueryBuilderState>().unwrap();
        assert_eq!(st.order_by_clauses.len(), 1);
        st.order_by_clauses[0].clone()
    }

    #[test]
    fn order_by_ascending_kwarg_controls_direction() {
        let sp = crate::ast::Span::ZERO;
        // `ascending: false` → DESC.
        let desc = orm_qb_order_by(
            empty_state(),
            vec![Value::Str("age".into())],
            sp,
            Some(false),
        )
        .unwrap();
        assert_eq!(one_order_clause(desc), "\"age\" DESC");
        // `ascending: true` → ASC.
        let asc = orm_qb_order_by(
            empty_state(),
            vec![Value::Str("age".into())],
            sp,
            Some(true),
        )
        .unwrap();
        assert_eq!(one_order_clause(asc), "\"age\" ASC");
    }

    #[test]
    fn order_by_ascending_kwarg_overrides_dash_prefix() {
        let sp = crate::ast::Span::ZERO;
        // `"-age"` would be DESC, but `ascending: true` overrides → ASC.
        let v = orm_qb_order_by(
            empty_state(),
            vec![Value::Str("-age".into())],
            sp,
            Some(true),
        )
        .unwrap();
        assert_eq!(one_order_clause(v), "\"age\" ASC");
        // No kwarg (`None`) → the `-` prefix decides → DESC.
        let v2 = orm_qb_order_by(empty_state(), vec![Value::Str("-age".into())], sp, None).unwrap();
        assert_eq!(one_order_clause(v2), "\"age\" DESC");
    }

    #[test]
    fn build_sql_with_limit_and_offset() {
        let mut s = empty_state();
        s.limit = Some(10);
        s.offset = Some(20);
        let sql = build_select_sql(&s, None);
        assert_eq!(
            sql,
            "SELECT \"id\", \"name\", \"age\" FROM \"users\" LIMIT 10 OFFSET 20"
        );
    }

    #[test]
    fn build_sql_override_limit_for_first() {
        // `first()` passes Some(1) as override; honored over the
        // user's state.limit (which could be != 1).
        let mut s = empty_state();
        s.limit = Some(50);
        let sql = build_select_sql(&s, Some(1));
        assert!(sql.ends_with("LIMIT 1"), "expected LIMIT 1, was: {sql}");
    }

    #[test]
    fn build_sql_negative_limit_clamps_to_zero() {
        let mut s = empty_state();
        s.limit = Some(-5);
        let sql = build_select_sql(&s, None);
        assert!(
            sql.ends_with("LIMIT 0"),
            "expected LIMIT 0 (clamp), was: {sql}"
        );
    }

    #[test]
    fn build_sql_skipea_fields_virtuales() {
        // Phase 10.4.a — fields with @has_many / @has_one do NOT go
        // in SELECT. We insert a virtual `posts` field and
        // verify that the real columns are emitted in order.
        let mut s = empty_state();
        s.fields.push(crate::ast::Field {
            name: "posts".into(),
            type_: crate::ast::TypeExpr::Generic {
                name: "List".into(),
                args: vec![crate::ast::TypeExpr::named("Post")],
            },
            default: None,
            decorators: vec![],
        });
        s.meta.relations.insert(
            "posts".into(),
            crate::types::RelationMetadata {
                kind: crate::types::RelationKind::HasMany,
                target_type: "Post".into(),
                fk_field: "user_id".into(),
                on_delete: crate::types::CascadeAction::Restrict,
                on_update: crate::types::CascadeAction::Restrict,
            },
        );
        let sql = build_select_sql(&s, None);
        assert!(
            !sql.contains("\"posts\""),
            "the virtual field `posts` should not be in the SQL: {sql}"
        );
        assert!(sql.contains("\"id\""));
        assert!(sql.contains("\"name\""));
        assert!(sql.contains("\"age\""));
    }

    #[test]
    fn build_sql_belongs_to_field_is_not_virtual() {
        // The field with @belongs_to IS real (it's the FK column).
        // It must appear in the normal SELECT.
        let mut s = empty_state();
        s.meta.relations.insert(
            "age".into(),
            crate::types::RelationMetadata {
                kind: crate::types::RelationKind::BelongsTo,
                target_type: "Profile".into(),
                fk_field: "age".into(),
                on_delete: crate::types::CascadeAction::Restrict,
                on_update: crate::types::CascadeAction::Restrict,
            },
        );
        let sql = build_select_sql(&s, None);
        assert!(sql.contains("\"age\""));
    }

